     "assessmentReport": [
      "2025, Achievement: two appropriate works, with at least two motifs or symbols explained in each, overall meaning linked to the question, an understanding of the artists' aims, and some appropriate terminology.",
      "2025, Merit: detailed, in-depth explanation of meanings, connections between features showing how meaning is built as a whole, the significance of imagery related to the artist's style and intentions, and some generalised context. Some discussed further motifs or related works.",
      "2025, Excellence: thorough understanding of movements and contexts, works chosen for their fit with the question, a focus on how meanings are constructed at the time of production, frequent return to the works, sophisticated terminology and no irrelevant content.",
      "2025, Not Achieved: one work only or works from the other area, no two clearly identified motifs in both works, personal interpretation without knowledge of artists or contexts, describing what is seen rather than explaining the imagery, discussing style instead of meaning, or works without enough scope for the question.",
      "2025, commentary: Q2 (individuals and/or groups) was most popular, and half of candidates combined a plate with a self-selected work. Common pairings were David's Napoleon Crossing the Alps with Géricault's Raft of the Medusa, and Daumier's Third-Class Carriage with Seurat's La Grande Jatte. Strong own choices included David's Death of Marat, Vigée Le Brun's Marie Antoinette, and Manet's Olympia and A Bar at the Folies-Bergère. Q1 candidates chose 'life' over 'architecture'. Art in Aotearoa was rarely attempted, and limited knowledge of the booklet works lowered achievement. Over half of digital responses exceeded the limit by about 1,000 words.",
      "2024, Achievement: two works with some meanings described, symbols or motifs linked to the question, some visual evidence and terminology, and limited context.",
      "2024, Merit: meanings explained in depth and evenly, with specific symbols or motifs from both works and accurate contextual influences.",
      "2024, Excellence: complementary works, coherent and fluent interpretation of symbols and motifs across both works, sophisticated terminology, and critical evaluation of original interpretations supported by expansive context.",
      "2024, commentary: in 'conflict and/or suffering', some addressed only suffering, which narrowed the response. In 'depiction of women', bringing in men (e.g. David's Lictors, Delacroix's Liberty) reduced depth and may reflect misreading or rote learning. Discussing how the movement shaped depictions helped towards Excellence."
     ],
