      "Questions use UNFAMILIAR contexts (e.g. clubmoss vs water milfoil, a cheetah, a hunting spider, sun and shade leaves) to test familiar processes. Most questions are a single extended 'discuss' prompt with bullet points, sometimes with a short labelling or equation part first.",
      "Questions rotate across the specified processes from year to year. 2024 tested respiration, photosynthesis and diffusion/SA:V/cell division. 2025 tested photosynthesis, respiration and enzymes. Any of photosynthesis, respiration, cell division/DNA replication, movement of materials or enzymes may appear in 2026."
