      "EN2: Demonstrate in-depth understanding involves providing reasons as to how or why genetic variation and change occurs.",
      "EN2: Demonstrate comprehensive understanding involves linking biological ideas about genetic variation and change. The discussion may involve justifying, relating, evaluating, comparing and contrasting, or analysing.",
      "EN3: Genetic variation and change covers sources of variation within a gene pool, and factors that cause changes to the allele frequency in a gene pool.",
      "EN4: Sources of variation are selected from mutation as a source of new alleles; independent assortment, segregation and crossing over during meiosis; monohybrid inheritance showing co-dominance, incomplete dominance, lethal alleles and multiple alleles; dihybrid inheritance with complete dominance; and the effect of crossing over and linked genes on dihybrid inheritance.",
      "EN5: Factors that change allele frequencies are selected from natural selection, migration and genetic drift.",
      "2026 specification: candidates must distinguish gametic from somatic mutations; Punnett squares for the specified monohybrid and dihybrid patterns, with expected proportions as a ratio, fraction, percentage or decimal; linked genes are considered to include sex linkage; genetic drift is considered to include the founder effect and genetic bottlenecks."
