      "2025, Merit: explained crossing over and segregation as reshuffling alleles to make unique gametes, and how they affect linked and unlinked genes; explained genetic drift in small populations; explained natural selection as changing allele frequency; explained selection pressures in two environments; defined complete and co-dominance accurately with blood-group examples.",
