      "2024, Merit: explained one allele per trait per chromosome to show why females can be tortoiseshell and males cannot; explained loss and fixation of alleles across two drift events; identified inbreeding as a cause of vulnerability; explained both Punnett squares; explained why dominant lethals must allow survival to adulthood and why recessive lethals persist (masked).",
      "2024, Excellence: linked sex to genotypes and phenotypes and to susceptibility to recessive sex-linked disorders; connected complete dominance, co-dominance and sex linkage; linked loss or fixation to at least two drift events for takahē; linked several problems and solutions, including bringing in alleles from other populations; discussed recessive lethality using both Punnett squares.",
