   "derivedGradeNotes": [
    "2026 Rules, Schedule 2 cl. 3(2): derived grades are available only where NZQA marks the work, which includes external examinations. 90843, 90844 and 90845 are all end-of-year examinations in 2026, delivered online (2026 Assessment Specifications: 'Assessment medium: Online digital examination'). The 2026 timetable lists Level 2 Business Studies on Monday 23 November 2026, afternoon session.",
    "2026 Rules, Schedule 2 cl. 3(3): the exclusions are NZ Scholarship, standards NZQA has published as ineligible, the dedicated co-requisite literacy and numeracy standards, and school-marked portfolio work verified by NZQA. None of the three Level 2 Business Studies externals falls into these groups. I found no NZQA statement making any of them ineligible, but I did not see a full list of ineligible standards.",
    "2026 Rules, Schedule 2 cl. 4(1) and 4(3): grades must come from quality-assured, pre-existing, valid, authentic, standard-specific evidence. That evidence must be a practice assessment matching the format and conditions of the external assessment, and grades must be submitted before the November examinations. EmaiLink August 2026 repeats that practice exams for derived grades must match the external format and conditions.",
    "For these papers, matching the format means: one question with multiple parts per standard; for 90843 and 90844 a provided business context, with ONE part that must use the student's own studied large NZ business (recalled without notes); for 90845 an unseen given context with resource material and no studied business; approved calculators allowed. The 2026 exam is online digital, so a typed practice paper is the closer match.",
    "NZQA derived-grade QA page: the evidence must cover ALL criteria of the standard, it must be certain the work is the student's own, and a suitably qualified second reader should verify it. Practice exams may be based on modified papers from previous years.",
    "2026 Rules change summary (as recorded for this site's Level 1 History research): derived grades are approved only after the exam cycle is complete, the student gets the better of the derived grade and the exam result, and Not Achieved is a valid derived grade."
   ],
