      "Codes (2024 and 2025): N0 no response or no relevant evidence; N1 very little Achievement evidence; N2 some Achievement evidence, partial explanations; A3 most Achievement evidence; A4 nearly all Achievement evidence; M5 some Merit evidence; M6 most Merit evidence; E7 some Excellence evidence, one part may be weaker; E8 all Excellence evidence points covered.",
      "The schedule lists Achievement, Merit and Excellence evidence points per sub-part. The marker counts how much of each tier is present across the whole paper. Excellence evidence is concentrated in the 'justify' sub-parts.",
