     "assessmentReport": [
      "2025, commentary: candidates who knew their own case study well did best; high achievers applied it directly to each question, used the business name and its operations, and linked terminology to effects on the business (e.g. how new technology affects expenses, sales and profits). Generic answers led to vagueness.",
      "2025, Achievement: limited or surface-level understanding of the case study, minimal use of it, concepts mentioned with weak links to business impacts, partial, vague or descriptive explanations.",
      "2025, Merit: general understanding of the business applied well, terminology used with some accuracy, links to business impacts partly explained, all parts answered with variable detail.",
      "2025, Excellence: thorough understanding of the chosen business applied consistently to all parts, specific business names, operations and details, accurate terminology with clear, logical links to impacts, every part answered fully.",
      "2025, Not Achieved: generic responses, business or context not identified, terminology applied incorrectly, parts not addressed.",
      "2024, commentary: most candidates linked well to the case material and handled flow, batch and job production confidently; shamrock answers were well written. Some confused economic and environmental sustainability, and economies of scale was harder. Many used generic solutions (firing staff, an advertising campaign) without context.",
      "2024, Achievement: generic, lacking context, described what happens and gave reasons, unrealistic impacts, freight responses without mentioning profit. Merit: used the chosen business or stimulus with business knowledge (profit margin, brand loyalty, productivity, economic sustainability) and fully explained one specific action after analysing reports. Excellence: integrated terminology with context, used NEW information to justify, distinguished economic from environmental sustainability, and compared the shamrock with tall, flat and matrix structures. Not Achieved: used the given case study in the part that required their own business, could not identify a suitable production process, left parts unattempted, gave what without why."
     ],
