   "discipline": "Each Level 2 Chemistry exam has three questions. Each question gets its own score code (N0–E8) from the a/m/e evidence ticks the marker gives to its parts, and the three codes are totalled out of 24. Achievement is earned by describing, identifying, naming, drawing and calculating correctly. Merit adds explained links (between structure, bonding or functional group and the property or reaction, or between a change and its effect on rate or equilibrium). Excellence adds a comprehensive answer that justifies, compares and contrasts, refers to the specific substances in the question, and uses chemistry conventions consistently (formulae, structures, equation arrows, units, signs and three significant figures). Length, memorised textbook definitions and generic answers not tied to the given substances never earn the higher ticks.",
