   "derivedGradeNotes": [
    "2026 Rules, Schedule 2 cl. 3(2): derived grades are available only where NZQA marks the work, which includes end-of-year external examinations. 91164, 91165 and 91166 are all examined in the Level 2 Chemistry exam on Monday 16 November 2026 at 2:00pm (NZQA 2026 timetable).",
    "2026 Rules, Schedule 2 cl. 3(3): the exclusions are NZ Scholarship, standards NZQA has published as ineligible, the dedicated co-requisite literacy and numeracy standards, and school-marked portfolio work verified by NZQA. None of these applies to 91164, 91165 or 91166. They are long-standing single-event external exams, and no source found lists them as ineligible.",
    "2026 Rules, Schedule 2 cl. 4(1) and 4(3): grades must come from quality-assured, pre-existing, valid, authentic, standard-specific evidence. That evidence must be a practice assessment matching the format and conditions of the external assessment, and grades must be submitted before the November examinations. EmaiLink August 2026 repeats that practice exams for derived grades must match the external format and conditions.",
    "For Level 2 Chemistry that means a printed paper sat under supervision with three questions per standard, all to be attempted, an approved calculator, and a copy of the resource booklet (periodic table with molar masses, and formulae). There must be NO IUPAC nomenclature reference sheet for 91165 (2026 specification). Each standard should be marked and graded separately, because each is its own derived grade.",
    "NZQA derived-grade QA page: the evidence must cover ALL criteria of the standard, it must be certain the work is the student's own, and a suitably qualified second reader should check it (for example a colleague checking boundary scripts). Practice exams may be based on modified papers from previous years. A school that reuses an NZQA past paper unchanged risks students having seen the published schedule.",
    "2026 Rules change summary: derived grades are approved only after the exam cycle is complete. The student gets the better of the derived grade and the exam result."
   ],
