      "EN3: Demonstrate understanding involves describing, identifying, naming, drawing, calculating, or giving an account of bonding, structure, properties and energy changes. This requires the use of chemistry vocabulary, symbols and conventions.",
      "EN3: Demonstrate in-depth understanding involves making and explaining links between bonding, structure, properties and energy changes, using chemistry vocabulary, symbols and conventions.",
      "EN3: Demonstrate comprehensive understanding involves elaborating, justifying, relating, evaluating, comparing and contrasting, or analysing links between bonding, structure, properties and energy changes. This requires the CONSISTENT use of chemistry vocabulary, symbols and conventions.",
      "EN4: Content is limited to: ionic, covalent and metallic bonding; intermolecular forces (no need to distinguish between types); Lewis structures, shape and polarity of simple molecules (no more than four electron pairs around any atom, including multiple bonds); molecular, ionic, metallic and covalent network substances; exothermic and endothermic reactions, including enthalpy changes for different amounts of substance, changes of state, and bond making and breaking; energy calculations using ΔrH, reaction stoichiometry and bond enthalpy.",
      "EN5: Properties are limited to hardness, malleability, ductility, electrical conductivity, melting and boiling points, and solubility. The 2026 specification adds that solubility refers to polar and non-polar solvents."
