      "Three questions, all to be attempted ('You should attempt ALL the questions in this booklet'). The 2025 booklet has pages 2–16. 91164 is sat in the same exam session as 91165 and 91166 (Monday 16 November 2026, 2:00pm). No time allowance per standard is printed.",
