      "Cut scores: 2025 N 0–7, A 8–13, M 14–18, E 19–24. 2024 N 0–7, A 8–13, M 14–18, E 19–24.",
      "2025 tick key (all three questions): N1 = 1a, N2 = 2a, A3 = 3a, A4 = 4a, M5 = 2m, M6 = 3m, E7 = 2e, E8 = 3e. Question Two's footer reads '2e with minor error' for E7 and '2e' for E8, so its top codes depend on accuracy rather than a third e.",
      "2024 tick key (all three questions): N1 = 1a, N2 = 2a, A3 = 3a, A4 = 4a, M5 = 3m, M6 = 4m, E7 = 2e, E8 = 3e.",
      "A single part can earn an a, m or e tick depending on depth. For example, 2025 Q1(c) on diamond's hardness and gold's malleability: identifying the bonding type earns an a, linking the bonding of ONE solid to its property earns an m, and comprehensively explaining the structure and bonding of BOTH solids earns an e.",
      "Calculations are usually ticked in steps: 'one step correct' earns the lower tick, and the correct answer with unit (and sign for ΔrH) earns the higher one. 2025 exemplars lost the e or m tick for a missing unit or minus sign, so the sign of ΔrH and 3 s.f. matter.",
