     "assessmentReport": [
      "2025, Achievement: identified electronegativity differences and defined electronegativity; drew Lewis diagrams or named shapes; calculated moles for enthalpy problems and the bonds broken or formed; counted bonding and non-bonding regions; identified particle types and attractive forces in solids; recognised that conductivity needs mobile charged particles, that malleability needs non-directional bonding, and that dissolving needs solute–solvent attractions; linked symmetry to polarity; chose correctly from limited options.",
      "2025, Merit: carried two consecutive steps of a thermodynamic calculation correctly; linked the strength of forces to the energy needed to melt a solid; linked metallic bonding and structure to malleability and ductility; described covalent network structure correctly; linked electron-region repulsion to bond angle; explained polarity through symmetry and dipole cancellation; drew hydrated ions in the NaCl diagram; linked polarity and solute–solvent attraction to solubility.",
      "2025, Excellence: gave thermodynamic answers to 3 s.f. with correct units and sign; justified the melting points of ionic and molecular solids from structure, bonding and energy; compared and contrasted the conductivity of solids including covalent network substances; used VSEPR to compare shapes and bond angles; justified polarity from electronegativity, bond polarity and symmetry; drew clear annotated dissolving diagrams (water dipoles and ion charges); justified the solubility of an ionic and a non-polar solute; used comparative language.",
      "2025, Not Achieved: wrote 'particle' instead of atom, ion or molecule; did not recognise diamond as a 3D covalent network; put conductivity down to mobile electrons only; did not explain that non-directional bonding lets layers of cations slide; misused ion, molecule, dipole and polar terms; called NaCl a polar molecule; gave ions the wrong charges in the dissolving diagram.",
      "2024, Achievement: as in 2025, plus converted mass to moles, labelled ΔrH, reactants and products on an energy diagram, and recognised that melting point relates to the strength of attractive forces.",
      "2024, Merit: linked the number of electron regions to parent geometry and bond angle; linked symmetry and polar bond strength to dipole cancellation or reinforcement; calculated bond enthalpy with at most a minor error; labelled an enthalpy diagram from a given equation with formulae and units; converted kg to g.",
      "2024, Excellence: annotated dissolving diagrams with water dipoles and ion charges; justified the solubility of ionic and non-polar solutes; compared shapes using electron regions, repulsion, bonded and non-bonded regions and bond angles; justified a metal's conductivity and malleability and LINKED these to its uses; 3 s.f. with correct units.",
      "2024, Not Achieved: used the wrong formulae in thermodynamic calculations; could not describe water's polarity; gave wrong bond angles; matched the wrong particles and forces to solid types; put conductivity down to electrons only; did not recognise that attractions are needed for dissolving.",
      "Both years, general commentary: Merit and above used correct terminology and conventions with attention to units and significant figures. Excellence needed evidence linked to the concept, related back to the examples in the question, with comparison where asked."
     ],
