      "Resource Booklet L2–CHEMR is supplied. The 2026 specification states that the IUPAC nomenclature reference sheet will NOT be provided, so naming must be from memory.",
      "Typical items: naming and drawing structures; reaction schemes with reagents, products and reaction types to fill in; tests to tell compounds apart (reagent, conditions, observations with starting and final colours); major and minor products (Markovnikov or Zaitsev); addition polymers; geometric and structural isomers; chain length linked to solubility and boiling point. Extended items often give bullet points to address."
