      "EN3: Demonstrate comprehensive understanding involves elaborating, justifying, relating, evaluating, comparing and contrasting, or analysing chemical reactivity. This requires the CONSISTENT use of chemistry vocabulary, symbols and conventions.",
      "EN3: Chemical reactivity is limited to rates of reaction and equilibrium principles.",
      "EN4: Rates of reaction: factors affecting rate (concentration, temperature, surface area and catalysts), and using collision theory, including activation energy, to explain them.",
      "EN5: Equilibrium principles: the dynamic nature of equilibrium; the effects of changes in temperature, concentration, pressure or a catalyst; the significance of Kc for homogeneous systems, which may involve calculations; acids and bases as proton transfer; properties of aqueous strong and weak acids and bases (conductivity, rate of reaction, pH); calculations involving Kw and pH for strong acids and bases."
