      "2025, Achievement: did one-step pH, [H3O⁺] and Kc calculations; recognised that surface area affects rate; defined acid, base and catalyst with memorised phrases; wrote simple dissociation equations and Kc expressions; identified the favoured direction under a stress; related pH to [H3O⁺] and conductivity to mobile charged particles; often missed units and significant figures.",
      "2025, Merit: linked greater surface area to more frequent successful collisions; explained how a catalyst works; wrote correct Kc expressions and interpreted their size; related conductivity and pH to the degree of dissociation; did two-step calculations with correct s.f. and units; explained temperature effects on both equilibrium and rate; used correct equilibrium arrows.",
