      "2025, Not Achieved: left questions blank; confused electrons with ions for conductivity; could not calculate pH or write Kc expressions; did not link surface area to rate; believed a catalyst supplies energy; wrote wrong dissociation equations and expressions.",
      "2024, Achievement: linked concentration to amount of particles and rate; defined a catalyst; calculated [H3O⁺] from pH; wrote an equation from a given Kc expression; substituted into Q; recognised conjugate pairs; wrote dissociation equations with correct arrows.",
      "2024, Merit: linked concentration to more collisions per unit time; compared gradients on a rate graph; compared Q with Kc and linked it to direction; linked a higher Kc to more products; linked higher temperature to the endothermic direction; related conductivity to the number of ions through the degree of dissociation; calculated pH of a strong base via [OH⁻].",
      "2024, Excellence: detailed answers on how concentration changes across sections of the graph; systematic, structured answers; used the mass–time graph and activation energy; correct units and s.f.; linked a temperature change to the Kc change to justify the exothermic or endothermic direction; distinguished strong and weak acids, bases and salts by pH and ions present and related this to conductivity.",
