   "derivedGradeNotes": [
    "2026 Rules, Schedule 2 cl. 3(2): derived grades are available only where NZQA marks the work, which includes end-of-year external examinations. 91200, 91201 and 91203 are all end-of-year examinations in 2026, delivered online (2026 Assessment Specifications, published October 2025).",
    "2026 Rules, Schedule 2 cl. 3(3): the exclusions are NZ Scholarship, standards NZQA has published as ineligible, the dedicated co-requisite literacy and numeracy standards (32403, 32405, 32406, 32412, 32413, 32415), and school-marked portfolio work verified by NZQA. None of 91200, 91201 and 91203 falls into these groups, so all are eligible in 2026. (No NZQA list naming these standards as ineligible was found.)",
    "2026 Rules, Schedule 2 cl. 4(1) and 4(3): grades must come from quality-assured, pre-existing, valid, authentic, standard-specific evidence. That evidence must be a practice assessment matching the format and conditions of the external assessment, and grades must be submitted before the November examinations. EmaiLink August 2026 repeats that practice exams for derived grades must match the external format and conditions and be quality assured.",
    "For each standard that means a supervised practice exam offering a choice of ONE from four unseen questions in the NZQA style, answered in extended paragraphs from memory (no notes, no resource booklet), with about 750–800 words as the guidance.",
    "NZQA derived-grade QA page: the evidence must cover ALL criteria of the standard, it must be certain the work is the student's own, and a suitably qualified second reader (panel marking or a colleague checking boundary scripts) should verify it. Practice exams may be based on modified papers from previous years.",
    "2026 Rules change summary: derived grades are approved only after the exam cycle is complete. The student gets the better of the derived grade and the exam result. Not Achieved is a valid derived grade, and NZQA records a school-reported N as V."
   ],
