      "EN2: Examine, with perception involves giving an explanation that shows insight into the ideas and values of the ancient Greeks and/or Romans, and drawing developed conclusions. A perceptive explanation may include reasons for similarities and differences, themes and patterns, and cultural expectations and codes of behaviour.",
      "EN3: Ideas and values may include but are not limited to: social relationships and the role of the individual; leadership and heroism; power and freedom; social and cultural traditions; religious beliefs; ideals of behaviour and national identity; literary conventions; influence on other cultures.",
      "EN4: Literary texts of the classical world may include: Homeric epic; Greek tragedy; Roman love poetry. Elaboration of specific contexts is provided in the Teaching and Learning Guide and the Assessment Specifications."
