      "Answer ONE of four questions with reference to a classical literary text, in paragraphs. The 2026 specification says questions cover leadership and/or heroism, social and cultural traditions, religious beliefs, and social relationships and/or the role of the individual, and may combine these ideas and values.",
      "No prescribed text; any classical literary text the student has studied (popular: Iliad, Odyssey, Antigone, King Oedipus, Argonautica, Aeneid, Lysistrata, Trojan Women, Medea, Horace).",
      "Aim for a concise answer of no more than 4–5 pages (750–800 words). The answer booklet has pages 2–11 plus extra space; the student writes the question number.",
