     "assessmentReport": [
      "2025, general: the strongest responses engaged with the specific question; plot retelling and rehearsed material not adapted to the question kept grades down. Using the planning space was linked to stronger answers.",
      "2025, Achievement: some knowledge of ideas and values but restricted; inaccuracies; a prepared answer deployed on the closest question; descriptive; textual examples cited without explaining their relevance.",
      "2025, Merit: informed knowledge; a question suited to the text and ALL parts addressed; question keywords reused; comparisons between texts; short quotations, description or Greek/Latin terms as support.",
      "2025, Excellence: perceptive, insightful; complete and thorough; quotations elaborated to show how they support the answer; comparisons with other texts, historical contexts or scholarship; text linked to its socio-historical or literary context; kept returning to the question.",
      "2025, Not Achieved: plot summary, limited knowledge, factual errors, misreading the question, pre-prepared answers. Common error: judging characters by modern values (e.g. Antigone as a hero) instead of classical ideas and values. Sappho made Merit and Excellence hard to reach.",
      "2024, Achievement: narrow understanding, uneven coverage of the question, plot-heavy, a modern Western lens. Merit: values behind characters' actions understood, detailed accurate examples. Excellence: links to religious influences, cultural expectations, original audience and performance context, material beyond the text (e.g. Antigone and Athenian democracy).",
      "2024, common errors: mixing Greek and Roman culture (Roman burial rites or pater familias for Greek texts); choosing non-heroes (Penelope) or modern definitions of heroism; pre-prepared 'good xenia / bad xenia' answers not applied to the question; Sappho fragments weakened explanations."
     ],
