      "2025, Achievement: one well-suited work known well; some relevant evidence, often vague, unexplained or not linked to a main idea; both parts of the question answered but one favoured.",
      "2025, Merit: depth of knowledge of the chosen work; analysed both parts of the question by explaining rather than describing or retelling; specific, relevant evidence linked to main ideas.",
      "2025, Excellence: perceptive insight into classical art and architecture; the question best matched to their knowledge; extensive, relevant evidence explained in detail; fluent, well structured; accurate, purposeful terminology; question wording used to stay focused.",
      "2025, Not Achieved: wrong work chosen (often from misunderstanding terminology); general information instead of an answer, including non-classical topics such as the Renaissance; too brief; unstructured sentences rather than paragraphs; no primary evidence from the work.",
      "2025, common errors: confusing stylistic technique with narrative; wrong terms (use pose not stance, drapery not costume, column not pillar); writing about more than one work at the cost of depth; long introductions.",
      "2024, Achievement: solid knowledge but unbalanced, heavy on myth, insufficient detail. Merit: all parts addressed throughout, consistent detail, art-historical terminology. Excellence: an art-historical lens or debate, comparison with earlier and later works, depth on one or two works, conclusions on historical, political or mythological significance.",
      "2024, Not Achieved and errors: general explanation without detail; context instead of features of the work; misreading key terms ('figures', 'influence', 'action', 'context'); describing composition, colour, background or myth instead of analysing the question; brief comments on the body when asked how figures convey meaning."
