     "assessmentReport": [
      "2025, Achievement: straightforward, undeveloped answers using the question's key words; minimal primary source references or correct Greek/Latin terms; sources relevant to the general context rather than the specific point; extensive background, excess narrative or rote-learned answers twisted to fit.",
      "2025, Merit: a range of primary sources, but not consistently analysed; good knowledge not linked to a wider context; some reliance on narrative; depth in areas only loosely tied to the question.",
      "2025, Excellence: points selected with discernment; excellent knowledge and interpretation of the question and context; source limitations addressed where appropriate; primary evidence used consistently with its significance explained; all parts addressed with insightful conclusions; links to wider social context or long-term consequences; no unnecessary narrative. Popular topics that allowed Excellence: the formation of the Delian League and the fall of the Roman Republic.",
      "2025, Not Achieved: little or no primary evidence; generalisations; misread or ill-suited question; pre-prepared answers with no specific examples; Greek, Latin or technical terms used incorrectly or not at all.",
      "2025, commentary: equal preparation on causes, consequences and context worked best for political questions; primary sources worked best built into the argument, and perception developed from analysing the values behind specific quotations.",
      "2024, popular topics: the fall of the Roman Republic and Octavian, the Persian Wars and Athenian Empire, Athenian reforms; a minority on Roman religion, education, and gender and class in Athens, Sparta and Rome.",
      "2024, commentary: quality over quantity; long tangents on context or consequences earned little credit; source limitations helped only when integrated into the argument, not as a final paragraph; using the question's keywords kept answers focused; for Q4 some did not clearly state which conflict they meant."
     ],
