   "discipline": "91898 is a written, online exam. The candidate answers ONE topic question with several parts, and the whole response gets one score from N0 to E8. Markers judge how deeply the student understands a computer science concept: Achievement covers how it works and is used, including its mechanisms and an opportunity it addresses; Merit adds its impact; Excellence adds its key problems or issues. Accurate terminology and specific, explained examples count. Feature lists, generic answers and writing about topics not asked for do not.",
