   "derivedGradeNotes": [
    "2026 Rules, Schedule 2 cl. 3(2): derived grades are available only where NZQA marks the work, including end-of-year external examinations. 91898 is an end-of-year online digital examination in 2026 (2026 Assessment Specifications; timetable Friday 27 November 2026, 2.00 pm), so it falls inside the scheme. (Rules summary carried over from the Level 1 History research file, which read the 2026 Rules directly.)",
    "2026 Rules, Schedule 2 cl. 3(3): the exclusions are NZ Scholarship, standards NZQA has published as ineligible, the dedicated co-requisite literacy and numeracy standards, and school-marked portfolio work verified by NZQA. 91898 is in none of these groups.",
    "Format history matters: 2025 was the first year 91898 was assessed as an end-of-year exam (2025 Assessment Report; A2025/13). In 2024 it was a digital common assessment task (DCAT) that schools ran in Term 3. Practice material modelled on the 2024 DCAT window, or on the earlier report format, does not match the 2026 conditions.",
    "2026 Rules, Schedule 2 cl. 4(1) and 4(3): evidence must be quality-assured, pre-existing, valid, authentic, standard-specific, and from a practice assessment that matches the format and conditions of the external assessment, with grades submitted before the November examinations (EmaiLink August 2026 repeats this).",
    "For 91898 that means: typed on a computer under supervision; a choice of ONE question on the 2026 topics (computer security OR encryption); multi-part matching-list, short and extended answers totalling about 800–1,500 words; no resources other than those supplied in the paper; and impact questions focused on human factors and social impact.",
    "NZQA derived-grade QA page: the evidence must cover ALL criteria (mechanisms and opportunity, impact, key problems or issues), must certainly be the student's own, and should be checked by a suitably qualified second reader. With a typed response, the school must also be sure no AI tools or internet access were used during the practice exam."
   ],
