     "assessmentReport": [
      "2025, overall: the first year as an exam, with results similar to previous years. 'The difference between grade levels came down to depth of understanding.' Lower responses described hardware; higher responses explained how data is processed and why technologies evolved.",
      "2025, Achievement: explained what car sensors feed into (AI deciding whether to brake or keep in lane), tied answers to the healthcare context rather than a generic description, explained the key exchange problem (interception, man-in-the-middle) rather than 'it's hard to share passwords', distinguished hashing from encryption and gave uses of hashing (password storage, file integrity), and answered all parts.",
      "2025, Merit: explained impact (e.g. faster diagnosis leading to better patient outcomes), explained why dip switches were insecure (limited combinations, easy to clone) compared with modern encryption, used correct terminology (not confusing encoding with encryption), and discussed human factors such as AI-driven social media's effect on behaviour or mental health.",
      "2025, Excellence: evaluated the effectiveness and limitations of concepts such as SHA-256 and neural networks rather than only describing them, gave real insight into future threats (quantum computing, deepfakes) in the future-proofing parts, linked sensors, AI processing and ethical issues into one answer for the car-safety question, and used the paper's diagrams to support explanations.",
      "2025, Not Achieved: misidentified the core concept (treating dip switches as high-tech encryption), wrote at length on topics not asked (viruses, coding), gave surface feature lists ('Cars have GPS'), answered a different question (AI in general when healthcare was asked), and left parts (b) and (c) blank or very brief.",
      "2024, Achievement: basic, acceptable understanding, often broad with partial answers; often one example where several were expected; attempted all questions but lacked depth.",
      "2024, Merit: read all questions before choosing a topic, gave two or more examples for most parts, and took clear positions on future-proofing or ethics.",
      "2024, Excellence: depth and breadth, several researched examples, links between computer science concepts, focused answers with correct terminology, some accurate historical facts.",
      "2024, Not Achieved and commentary: claims without examples, little technical detail or vocabulary (especially for AI), no discussion of machine learning or other techniques behind chatbots or driverless cars. Results were even across the three topics. Attempting all parts helped, because later parts sometimes lifted a response to Achievement."
     ],
