      "EN2: Elements refer to role, time, place, situation, action, tension, mood, contrast, focus and symbol. Conventions refer to ways of working in drama or theatre that explore meaning, deepen understanding, or are established practices. Techniques refer to use of voice, body, movement and use of space. Technologies refer to sound, lighting, set, costume, properties, stage design, special effects and make-up.",
      "EN2: Live performance refers to drama or theatre performance. The meaning of the performed text may relate to themes, issues, concerns, subtext, or dramatic intention."
