      "Three compulsory questions, each with (a) explain and (b) discuss. 2025: Q1 Convention (performed in), Q2 Status (performed in or seen), Q3 Technology and mood (seen). 2024: Q1 Convention (performed in), Q2 Tension (performed in or seen), Q3 Two technologies in combination and dramatic intention (seen).",
      "Candidates record the title and playwright or theatre company for each question. A glossary of elements, conventions, techniques and technologies opens the paper.",
