      "2025 codes (Question One; Two and Three follow the same pattern). N1: identifies how the convention was used and/or how it deepened understanding. N2: explains (a) briefly. A3: explains (a) simply and discusses (b) simply, limited reference to evidence. A4: explains (a) and discusses (b), with evidence. M5: explains and discusses clearly, with evidence. M6: explains and discusses in detail, with detailed evidence. E7: discusses (b) with some perception AND connections to the candidate's own and/or wider world, with well-chosen evidence. E8: discusses (b) perceptively with those connections, with well-chosen evidence.",
