     "assessmentReport": [
      "2025 and 2024, general: many answers were superficial, answered only part of a question, or left parts blank. Candidates often copied model answers or past schedules instead of adapting to the question's context. Bullet points are a planning framework and should be addressed directly. Annotated diagrams improved answers. Higher grades came from detailed explanation applied to the new context, correct vocabulary and concise writing.",
      "2025, Achievement: drew and labelled diagrams; described magma formation and andesitic magma properties; described stratovolcano layering; defined a fault, focus and epicentre; described shallow vs deep earthquake impacts and energy loss with depth; defined a tsunami as water displacement and linked plate uplift to water movement; described one wave property and at least one caldera eruption stage.",
      "2025, Merit: explained how magma density varies and less dense magma rises through cracks; explained seawater lowering the melting point of the Pacific Plate and silica from the Australian Plate; linked andesitic magma to steep stratovolcano sides; linked energy to depth or distance from the epicentre; explained uplift generating a tsunami and behaviour in deep and shallow water; explained one stage of an underwater eruption.",
      "2025, Excellence: explained andesitic magma formation and the rise in silica through Earth processes; explained in depth how earthquake energy relates to depth and distance; explained uplift as a tsunami source with the energy transfers; linked low energy loss in deep water and friction with the seabed in shallow water; explained the stages of a submerged caldera.",
      "2025, Not Achieved: confused hotspot with subduction volcanism; generic statements about magma; could not identify the plates or their movement; listed every possible tsunami cause instead of the relevant one; did not understand 'submerged'.",
      "2024, Achievement: described hotspot volcano formation, basaltic magma, tuff rings and shield volcanoes; defined focus and epicentre and described shallow vs deep impacts; defined a tsunami, described energy transfer from uplift, and described amplitude or frequency at a stated location.",
      "2024, Merit: linked magma rise to density; explained magma moving through crustal cracks and basaltic magma forming scoria cones or shield volcanoes; linked earthquakes to friction and locked plates, and energy to depth or distance; explained how uplift generates a tsunami and deep vs shallow water behaviour.",
      "2024, Excellence: linked hotspot formation to basaltic magma and crustal movement over the hotspot; linked basaltic magma properties to eruption types and landforms; explained how depth and distance relate to damage; linked tsunami run-up and inundation to shoreline height.",
      "2024, Not Achieved and common errors: generic statements about all magma types or tsunami; could not identify the plates or listed all plate movements without relevance; limited statements or poorly labelled diagrams. Run-up height and inundation were poorly understood, and many could not link magma rise to density."
     ],
