   "slug": "english",
   "discipline": "The two studied-text exams (91098 written, 91099 visual or oral) are single essays, each marked as a whole with one score from 0 to 8. The unfamiliar-text exam (91100) has three short analytical responses, each scored 0 to 8 and totalled out of 24. In all three, markers judge the step from analysing (A) to analysing convincingly, with reasoned and connected interpretations (M), to analysing perceptively, with insightful or original interpretations (E). The analysis must show how deliberate crafting creates meaning, and it must be supported by specific, relevant detail from the text. NZQA states repeatedly that quality is rewarded, not length, and that plot summary, a list of techniques or a rote-learned essay does not reach the higher grades.",
   "parallelHint": "for 91098 and 91099, a different studied text (or the same text answering a different question from the published list, which focuses on a different aspect: purpose and audience, ideas, language features or structure); for 91100, a different set of three unseen texts (prose, poetry, non-fiction) of similar length and Level 7 difficulty, with new 'Analyse how…' questions",
