      "EN5–6: Studied texts may be from New Zealand or the wider world. The student may refer to one or more texts within one type: novel, non-fiction, print media, drama, short stories, poetry or song lyrics, digital text, or a combination for inter-textual studies.",
      "Schedule (2025): 'insight' and 'originality' are judged in the context of a student working at Curriculum Level 7. At Achievement, awareness of deliberate crafting may be shown by implication."
