      "N0: no response, or no relevant evidence. N1: attempts to address the question. N2: states a relevant idea, shows awareness of the use of the specified aspect(s) and includes details from the text(s), but does not yet fulfil Achievement.",
      "A3: fulfils the intent of the Achievement criteria, although some parts may be partial or weak. A4: securely fulfils the intent of the Achievement criteria. The Achievement criteria are: a structured essay using analysis terminology appropriately; addresses the question and its specified aspect(s); explores a relevant idea; shows awareness (possibly by implication) that effects and meanings are deliberately crafted; includes specific, relevant details.",
      "M5: fulfils the intent of the Merit criteria, although some parts may be imbalanced or limited. M6: securely fulfils them. The Merit criteria are: terminology used to support points; addresses the question CONVINCINGLY; a reasoned discussion with most interpretations connected; judgements about how effects relate to the text's purpose; a range of specific details woven in.",
