     "assessmentReport": [
      "2025, Achievement: a recognisable essay structure of sufficient length, with key words from the question framing the ideas. Both parts of the question were addressed, but unevenly. Evidence was present but weakly unpacked, techniques and purpose were identified at a basic level, and the analysis stayed on the surface. Typical features were a formulaic structure, pre-learned ideas and little sustained argument.",
      "2025, Merit: sustained, well-organised responses focused on the question, with both parts balanced and woven through the paragraphs. Evidence was wide and well chosen (often several quotations per point) and unpacked to show how and why techniques were used. These candidates evaluated purpose and its effect on the reader, connected paragraphs into a cumulative argument, made real-world links that kept textual focus, and wrote a convincing conclusion.",
      "2025, Excellence: fluent, cohesive responses driven by a central argument, with original, perceptive interpretations beyond taught ideas. Evidence was integrated seamlessly (quotation, paraphrase, summary), and these candidates showed how language features work together and evaluated crafting choices with authority. Contextual links were woven into the argument, insight was consistent throughout, and the language was precise, with a personal voice showing judgement.",
      "2025, Not Achieved: texts too simple or below Level 7, significantly under-length responses, misreading or ignoring the question (often addressing only one part), heavy plot summary, vague or irrelevant evidence, little awareness of authorial craft, and rote-learned answers poorly adapted to the question.",
      "2025, commentary: higher grades went to candidates who understood key vocabulary (especially 'structure') and read the question wording carefully. Texts with rich, debatable ideas and sophisticated crafting enabled higher grades (Shakespeare, dystopian and modern novels, Carol Ann Duffy, war poetry, NZ, Māori and Pasifika writers). Limiting texts were below Level 7, plot-driven, familiar from earlier years, or self-selected without guidance. Song lyrics rarely got above Achievement, and Young Adult fiction and picture books limited candidates. A large volume of evidence is not the same as perceptive analysis.",
      "2024, Achievement: matched text and question, used the question's key words to structure the response, addressed both parts unevenly, used some quotations or plot points unpacked simply, explored context in a formulaic way, and analysed techniques in isolation.",
      "2024, Merit: a clear thesis from the outset, both parts addressed with detailed, specific evidence unpacked thoroughly, two or three key points developed in depth and linked, confident technical language, an understanding of how the text was crafted, meaningful real-world links and personal engagement.",
      "2024, Excellence: controlled their own thesis rather than a rote-learned response, showed nuanced, mature understanding of the text's context, construction and larger significance, integrated evidence and explanation seamlessly, and linked precise language features to the author's purpose.",
      "2024, Not Achieved: texts without enough scope (self-selected song lyrics, online fan fiction), plot summary, a question poorly suited to the text, ignoring or misunderstanding the specified aspect, rote-learned responses, well under length, addressing only part of the question, and no awareness of deliberate use of language.",
      "2024, commentary: class-taught texts outperformed self-selected or Wide Reading texts. Texts exploring 'grey' or debated ideas did better (Lord of the Flies outperformed The Hate U Give). Lengthy responses that drifted from the question could not earn Excellence: 'plethora is not the same thing as perceptive'."
     ],
