     "assessmentReport": [
      "2025, Achievement: addressed the question's key words, but unevenly. These responses used straightforward terminology, gave more plot than analysis, and did not address wider purpose. Typical features were a formulaic structure, reliance on a single scene, and no overall thesis, which left the points disconnected. The second part of the question was often left to the end.",
      "2025, Merit: convincing understanding supported by relevant details and references to visual or oral features, with detailed responses that dealt convincingly with both parts. They engaged with context or audience positioning, though not always fully integrated, and made personal or wider-world links where relevant.",
      "2025, Excellence: a strong thesis with the discussion kept focused on it, perceptive links between language features and the analysis, a mature appreciation of wider context, clear logical structure with consistently insightful evidence, and an understanding of genre conventions (including when they are subverted to shape audience perception).",
      "2025, Not Achieved: questions inappropriate for the text, not addressing the question or its aspects, plot-driven responses, not enough evidence for the descriptive first half of the question, weak fluency, and repeated rather than developed points.",
      "2025, commentary: many candidates treated film like written text and relied too heavily on DIALOGUE as a language feature. Film language features must be understood on their own terms. Candidates could identify techniques but struggled to link them to the director's purpose. Digital responses were often far longer than 750–800 words, and the length sometimes lowered grades. Films commonly taught at Level 1 (e.g. Remember the Titans, The Blind Side, Whale Rider, Hunt for the Wilderpeople, Boy, The Help) limited achievement.",
      "2024, Achievement: addressed the question's key words, often unevenly, with straightforward terminology and at least one main idea, but focused on plot at the expense of analysis and did not address wider purpose.",
      "2024, Merit: detailed, comprehensive responses showing awareness of the whole text and of the director's intent, integrating relevant visual or oral features, with some perception that was not sustained.",
      "2024, Excellence: went straight to relevant detail, analysed the impact on the audience, sustained a strong thesis with insightful links between language features and analysis, discussed the director's purpose extensively, and showed mature appreciation of wider context.",
      "2024, commentary: some responses showed Merit-level depth but were graded as borderline passes or N2 because the candidate misunderstood what counts as a visual or oral language feature. The specification lists the common features. The Blind Side, Dark Horse, The Help and Fish Skin Suit consistently produced Not Achieved responses."
     ],
