      "Each of the three questions gets its own score code from N0 to E8. The three codes are TOTALLED out of 24.",
      "Cut scores (2024 and 2025 schedules): Not Achieved 0–6, Achievement 7–12, Merit 13–18, Excellence 19–24.",
      "Per-question codes (generic for every question): N0 no response or no relevant evidence. N1 attempts to address the question. N2 states a relevant idea. A3/A4 fulfils (partially or weakly / securely) the Achievement criteria. M5/M6 fulfils (with some imbalance / securely) the Merit criteria. E7/E8 fulfils (with some imbalance / securely) the Excellence criteria.",
      "Achievement criteria (2025 schedule): engages with the text by addressing the question, explores a relevant idea using analysis terminology, shows awareness that meaning has been deliberately crafted, and includes specific, relevant details.",
      "Merit adds a reasoned, clear discussion, awareness of meaning crafted for a particular purpose, and a range of details woven in. Excellence adds an insightful or original argument, judgements about how effects relate to purpose, and a range of details woven in to support the argument.",
      "Each question's schedule lists text-specific possible ideas and evidence (e.g. 2025 Text C: 'peak-geek drama', dynamic verbs 'blurred', 'erupted'). These are indicative, not required.",
      "Because scores are totalled, one missing answer costs up to 8 marks: two A4 answers with no third answer total 8 (Achievement), while three A4 answers total 12."
