     "assessmentReport": [
      "2025, Achievement: linked the text's content to the question (sometimes with misunderstanding), identified at least one technique with specific evidence, discussed some parts of the text more fully than others, interpreted effects at surface level, and addressed purpose in an underdeveloped way.",
      "2025, Merit: explored ideas in depth with quotations developed in detail, analysed the 'so what' of statements, began relevant links beyond the text, explained HOW the author's intent was fulfilled rather than stating it, covered techniques across the whole text (including tone and structure), and linked examples into a developed response rather than a list.",
      "2025, Excellence: genuine, insightful links beyond the text, a clear relationship between the wider message and specific aspects, systematic coverage of the whole text with techniques integrated seamlessly, perceptive understanding of the text as a crafted whole, and an explanation of how language, tone and structure work together (some compared beginnings and endings). These responses were driven by ideas rather than by a catalogue of language features.",
      "2025, Not Achieved: paraphrased plot or events, identified devices without linking them to the question, listed devices without explaining their effect, answered fewer than three questions, or used irrelevant or inaccurate examples.",
      "2025, commentary: analysing fewer techniques in depth was more valuable than listing many. Essays are not needed. Excellence responses integrated quotations smoothly and made perceptive judgements across all three texts.",
      "2024, Achievement: framed the answer around the question's wording, often paraphrasing in a formulaic way, engaged with at least one relevant idea with quoted evidence, and identified techniques without drawing conclusions (a 'shopping list').",
      "2024, Merit: linked each feature to why it was used, opened with a thesis making a claim about the text, analysed several techniques and linked them to the question, to each other and to purpose, and unpacked evidence rather than just quoting it.",
      "2024, Excellence: understood the piece as a whole rather than dissecting features one by one, developed an original idea throughout, showed techniques working together, generalised about underlying themes with wider-world links, and explored how mood and nuance were created. Excellence answers analysed the whole text for each question, while Merit answers tended to focus on one or two key points.",
      "2024, commentary: in Q1 many focused on Eugene rather than on his relationship with his mother. In Q3 candidates confused the author's response with the audience's. Many misidentified language features, and copying large amounts of text did not help. Some handwriting was illegible."
     ],
