      "2025, Merit: more detailed explanation of the environment, clear links between processes and elements, and detailed case study material throughout.",
      "2025, Excellence: well-structured, analytical and insightful answers, with high-quality diagrams or sketch maps and precise terminology.",
      "2025, Not Achieved: missed the question, purely descriptive, little case study evidence, or irrelevant material, including a lot of cultural content the question did not ask for.",
      "2024, general: out-of-date or inaccurate case study information capped results at the higher grades. Most candidates understood how the environment forms and changes and how people perceive it; detailed, annotated diagrams helped. (The 2024 report labels this section '91420', which appears to be a typo for 91240.)",
      "2024, Excellence: comprehensive, insightful, well-structured answers with detailed case study evidence throughout, concepts such as change applied explicitly, and annotated diagrams. Not Achieved: did not address the question or used a pre-prepared answer, left parts blank, or wrote only about cultural changes to the environment."
