      "EN3: Development is the standard of living and quality of life of people; it varies across space and changes over time at individual, local, national and global scales. Case study evidence is information about communities, areas or countries at different stages of development. Factors contributing to differences may be natural and/or cultural. Strategies for reducing differences are actions taken or proposed by governments and/or non-governmental organisations.",
      "EN4: Aspects are selected from: characteristics of development; ways development can be measured (quantitative and qualitative indicators, and their limitations); factors contributing to differences in development; strategies for reducing differences in development."
