      "2026 change: none found in the specification. The 2026 and 2025 specifications both say 'There will be ONE question with multiple parts' and require case studies of communities, areas or countries at different stages of development. The aspects tested change from year to year (2024: one factor and one strategy; 2025: two strategies).",
