      "Cut scores (2024 and 2025 schedules): Not Achieved 0–2, Achievement 3–4, Merit 5–6, Excellence 7–8.",
      "2025 codes (two strategies). N1: briefly describes one or two strategies for reducing differences in development. N2: describes one or two strategies. A3: briefly explains ONE strategy. A4: explains ONE strategy. M5: explains in detail TWO strategies. M6: as M5, with detailed supporting case study evidence. E7: fully explains, with some insight, TWO strategies. E8: fully explains, with insight, TWO strategies.",
      "2024 codes (factor and strategy). N1–A4 needed a factor OR a strategy (limited understanding at N1, some understanding at N2, brief explanation at A3, explanation at A4). M5–E8 needed a factor AND a strategy, explained in detail at Merit and fully at Excellence. Evidence lines rose from 'some supporting case study evidence' to 'integrates comprehensive supporting case study evidence throughout', with insightful use of concepts and terminology at Excellence.",
      "So in both years Achievement can be reached on ONE well-explained element, but Merit and Excellence need BOTH elements the paper asks for.",
