     "assessmentReport": [
      "2025, commentary: the standard requires evidence from two or more case study locations; responses relying on a single location could not reach higher-level performance.",
      "2025, Achievement: one strategy, with evidence and outcomes, for only one location; a generalised second strategy, or a factor, indicator or concept written about instead; case study evidence not used clearly throughout; more descriptive and lacking detail.",
      "2025, Merit: two specific strategies with good understanding of each, detailed evidence from two named areas, and a detailed explanation of how each strategy improved development and so reduced the difference between the locations.",
      "2025, Excellence: two clearly identified locations with differing levels of development, case study evidence integrated throughout, a comprehensive explanation of how the strategy reduced the development gap, clear outcomes showing the reduction, and effective terminology and concepts showing insight.",
      "2025, Not Achieved: unrelated to the question, general answers not focused on specific locations or outcomes, a focus on gender differences rather than differences between locations, or description without explaining how strategies reduced differences.",
      "2024, commentary: candidates had to compare two case study areas; those who focused on one, or treated the second only implicitly or briefly, could not show a difference in development and were restricted from higher grades.",
      "2024, Achievement: basic explanation of factors and strategies and poor use of the planning space. Merit: more detailed evidence, though one area was sometimes less detailed; several factors described rather than one explored in depth; planning box used to show logical thinking. Excellence: balanced, comparative data for both areas and an explanation of how development levels were shaped. Not Achieved: described without explaining factors or strategies."
     ],
