      "2025 concepts strand (location, accessibility, change, natural and cultural environment): N1 attempts ONE aspect; N2 some understanding of ONE; A3/A4 some understanding of TWO; M5 explains in some detail TWO; M6 explains in detail TWO; E7 comprehensively explains ALL aspects with some insight and terminology; E8 as E7 with terminology consistently throughout.",
