   "derivedGradeNotes": [
    "2026 Rules, Schedule 2 cl. 3(2): derived grades are available only where NZQA marks the work, which covers external examinations. 91235 and 91238 are both end-of-year examinations in 2026 (2026 Assessment Specifications).",
    "2026 Rules, Schedule 2 cl. 3(3): the exclusions are NZ Scholarship, standards NZQA has published as ineligible, the dedicated co-requisite literacy and numeracy standards (32403, 32405, 32406, 32412, 32413, 32415), and school-marked portfolio work verified by NZQA. Neither Health standard falls into these groups. I found no NZQA list naming 91235 or 91238 as ineligible, so both are treated as eligible (my reading of the rules).",
    "2026 Rules, Schedule 2 cl. 4(1) and 4(3): grades must come from quality-assured, pre-existing, valid, authentic, standard-specific evidence, from a practice assessment that matches the format and conditions of the external assessment, and they must be submitted before the November examinations. EmaiLink August 2026 repeats that practice exams for derived grades must match the external format and conditions and be quality assured.",
    "For Level 2 Health that means: a resource booklet with a scenario and several resources that students have NOT seen before; a single multi-part question covering influences (personal, interpersonal, societal), short- and long-term consequences, and strategies; students writing under supervision with no notes. In 2026 the real exam is online digital only, so a practice exam typed on computers matches best.",
    "91238 practice papers must keep to the standard's scope: a power imbalance in interactions with others (discrimination, intimidation, victimisation, harassment, bullying). EN3 rules out sexual abuse as a focus. 91235 papers must not focus on suicide or eating disorders (EN4). A practice paper outside this scope is not valid evidence.",
    "NZQA derived-grade QA page: the evidence must cover ALL criteria of the standard, it must be certain the work is the student's own, and a suitably qualified second reader (panel marking or a colleague checking boundary scripts) should verify it. Practice exams may be based on modified papers from previous years, but a booklet students have already worked through in class is not unseen.",
    "2026 Rules change summary: derived grades are approved only after the exam cycle is complete. The student gets the better of the derived grade and the exam result. Not Achieved is a valid derived grade."
   ],
