     "verified": "2026-10-25",
     "title": "Analyse an adolescent health issue",
     "criteria": {
      "achieved": "Analyse an adolescent health issue.",
      "merit": "Analyse in depth, an adolescent health issue.",
      "excellence": "Analyse comprehensively, an adolescent health issue."
     },
     "notes": [
      "EN2: Analyse an adolescent health issue involves providing an explanation of: influences on the issue; consequences for well-being; health enhancing strategies that promote well-being in relation to the issue.",
      "EN2: Analyse in depth, an adolescent health issue involves providing a detailed explanation of: how the influences have contributed to consequences for well-being in relation to the issue; how the strategies for promoting well-being are related to the influences.",
      "EN2: Analyse comprehensively, an adolescent health issue involves making connections within and/or between influences, consequences and strategies to show critical understanding of the underlying concepts.",
      "EN3: An analysis of an adolescent health issue typically includes an explanation of personal, interpersonal, and societal perspectives.",
      "EN4: An adolescent health issue is one affecting the well-being of adolescents and which is a matter of public concern. Examples include stress management, adolescent alcohol use and misuse, enhancement of relationships, influences of body image, cannabis or other drug use, food related issues, maintenance of sexual/reproductive health. Focusing on suicide or eating disorders is not appropriate.",
      "EN1: assessment reflects the underlying concepts of the curriculum (hauora, the socio-ecological perspective, health promotion, attitudes and values). The 2026 specification says candidates must apply these concepts to unfamiliar contexts, which may be sensitive."
     ],
     "examFormat": [
      "2026 change: the exam is an ONLINE DIGITAL examination (2026 Assessment Specifications, October 2025). In 2025 it was offered either online or on printed paper (2025 specification), and the published 2025 and 2024 papers are the printed versions with a pull-out resource booklet.",
      "One multi-part question built on a separate resource booklet (91235R) that candidates have not seen before: a scenario or set of resources about one adolescent health issue. Candidates use the resource material AND their own knowledge of personal, interpersonal and societal factors affecting New Zealand teenagers.",
      "Typical structure (2024 and 2025): (a) influences, one personal, one interpersonal and one societal; (b) consequences for well-being, short-term for the individual and long-term (2025: for the wider New Zealand community); (c) strategies, one personal, one interpersonal and one societal, each explained in relation to the influences and consequences. In 2024 the wider-community consequences were a separate part (c) and strategies were part (d).",
      "There is no choice of questions: candidates attempt all parts. Planning pages are provided but not marked. No word limits or time allowance are printed on the paper, and NZQA states quality is valued over length.",
      "Contexts: 2025 excessive screen time over sleep (Resources A to F: a teen group chat, research and news articles, an infographic, a tip sheet, a class case study); 2024 stress and anxiety (the Ari scenario, Resources A to D)."
     ],
     "scoring": "whole",
     "markingModel": [
      "The paper is marked HOLISTICALLY: the schedule gives one set of score codes for the whole response, and the exemplars record a single code for 'Question One' that is also the total.",
      "Cut scores (2024 and 2025 schedules): Not Achieved 0–2, Achievement 3–4, Merit 5–6, Excellence 7–8.",
      "2024 codes. N0: no response or no relevant evidence. N1: some relevant information but does not address the question. N2: uses resource information and attempts to analyse, but not enough for Achievement. A3: meets the intent of Achievement, though partial or weak. A4: securely meets Achievement. M5: meets Merit, though it may lack consistency and structure. M6: securely meets Merit with in-depth analysis of influences, consequences and strategies. E7: meets Excellence, though it may lack consistency and structure. E8: securely meets Excellence, making connections within and/or between influences, consequences and strategies to show critical understanding.",
      "2025 codes. N1/N2: sparse information, some answers not attempted, or only lists from the resources with no explanation or own knowledge. A3/A4: explains some influences, consequences and strategies (may be partial or weak). M5/M6: explains them with some detail and shows some critical understanding, such as selecting the more critical strategies, explaining why they are health-enhancing, and linking influences, consequences and strategies. E7/E8: explains in detail and shows critical understanding, such as justifying why strategies are health-enhancing and linking influences, consequences and strategies.",
      "2025 part-level guidance: (a) A = describes TWO of the factors, M = explains how they influence teenagers; (b) A = explains the impact on EITHER the teenager OR the wider NZ community, M = explains in depth BOTH short-term personal and long-term community impacts, E = analyses both; (c) A = recommends strategies and explains how they enhance well-being, M = explains how the strategies relate to the influences, E = explains how they address the influences and maintain positive consequences.",
      "The sample evidence in the schedules is not exhaustive. Accurate own-knowledge points that fit the scenario earn credit."
     ],
