     "assessmentReport": [
      "2025, Achievement: described personal, interpersonal and/or societal influences; explained EITHER short-term personal impacts OR long-term societal impacts; explained health-enhancing strategies; used resource information with some explanation, with some inconsistencies or inaccuracies.",
      "2025, Merit: explained influences in depth; explained short-term personal AND long-term societal impacts linked to the influences; linked strategies to influences or consequences; combined resource information with their own knowledge.",
      "2025, Excellence: in-depth understanding of personal, interpersonal and societal factors throughout; comprehensive short-term consequences and insightful long-term impacts on the wider NZ community; strategies that explicitly addressed the influences and explained how they would minimise harm; strategies explicitly linked to both influences and consequences; resources used critically alongside own knowledge.",
      "2025, Not Achieved: brief descriptions often copied from the resources without explanation; parts left unanswered, especially wider-community impacts and the interpersonal and societal strategies; long-term societal impacts that just repeated short-term personal ones framed as 'many teenagers'.",
      "2025, commentary: social media was often wrongly placed as a personal or interpersonal influence; it is predominantly SOCIETAL. Consequences must be negative, not positive. Strategies must address the influencing factors and explain how they minimise impacts. Candidates do NOT need to explain negative consequences of their strategies.",
      "2024, Achievement: explained influences, short- and long-term consequences and strategies using the scenario and resources with some further explanation; some inconsistencies or inaccuracies accepted.",
      "2024, Merit: in-depth explanation of influences, short- and long-term consequences with some insight into societal consequences, strategies linked to the influences and consequences, and own knowledge combined with the scenario and resources.",
      "2024, Excellence: in-depth understanding of all three levels of factors throughout, comprehensive consequences including insightful long-term impacts on NZ society, strategies explicitly addressing the influences and minimising consequences, critical use of resources, and understanding of health concepts such as health promotion.",
      "2024, Not Achieved: brief descriptions without explanation, incomplete answers (especially societal aspects), listed or bullet-pointed resource points, and influences or strategies not clearly identified as personal, interpersonal or societal.",
      "2024, commentary: candidates often confused personal and interpersonal influences by writing interpersonal factors from the individual's point of view (e.g. 'Ari wanting to make his parents proud' instead of the pressure others place on Ari). Interpersonal strategies were often mislabelled as personal: they should be what others (whānau, friends, teachers) do. Copying resource examples, bullet points and short answers weakened consequences."
     ],
