     "notes": [
      "EN2: Examine sources involves using one or more historical skill(s) to show understanding of sources. Showing understanding involves selecting and explaining evidence relevant to the question being investigated.",
      "EN2: Examine sources in-depth involves using one or more historical skill(s) to show a thorough understanding of sources. Showing thorough understanding involves selecting detailed evidence relevant to the question being investigated and explaining it.",
      "EN2: Comprehensively examine sources involves using one or more historical skill(s) to show perceptive understanding of sources. Showing perceptive understanding involves 'reading between the lines' to draw conclusions that go beyond the immediately obvious, and/or to raise relevant questions (where appropriate) that demonstrate a high degree of engagement with the source. It could involve selecting and explaining evidence with an awareness of the limitations of either the evidence or the basis for making assumptions about it.",
      "EN3: Sources may include documents, images, graphs, maps, articles, speeches, cartoons and textbooks (paraphrased).",
      "EN4: Historical skills include close reading, comprehension and extracting meaning (paraphrased).",
      "EN5: Historical skills are used to identify concepts such as: perspectives; reliability or bias; continuity and change; intent and motivation; cause and effect.",
      "EN6: An historical event can be a specific event in time, a broader historical development or movement, or a person's role in and contribution to one of these (paraphrased).",
      "EN7: An event is of significance to New Zealanders if it happened in New Zealand, or was international and involved or influenced New Zealanders (paraphrased)."
     ],
     "examFormat": [
      "2026 change: the exam is ONLINE DIGITAL only (the 2025 specification allowed 'online digital examination or printed paper'), and the specified context changes to 'the changing role of women in public and political life' (2025: kotahitanga movements in Aotearoa New Zealand from the nineteenth century to the present day). No other format change is stated.",
      "Candidates receive a resource booklet of a variety of primary and secondary historical sources on the specified context, and write paragraph-length answers. The context is announced in the specification; the sources themselves are unseen.",
      "Three questions, all compulsory, each tied to named sources. 2024 and 2025 pattern: Q1 a 'what/why' question using the Introduction and at least TWO of the first group of sources; Q2 a perspectives, change/continuity or comparison question using at least TWO of a second group; Q3 a usefulness or reliability question about named sources, inviting concepts such as intent, motivation and reliability.",
      "The concepts tested come from EN5 (perspectives, reliability or bias, continuity and change, intent and motivation, cause and effect).",
      "No time allowance or word guidance is printed on the papers. The 2025 answer booklet had pages 2–8 plus extra space."
     ],
     "scoring": "question",
     "markingModel": [
      "Each of the three questions is marked separately against its own N0–E8 descriptors and the three codes are TOTALLED (maximum 24).",
      "Cut scores 2024 and 2025: Not Achieved 0–7, Achievement 8–13, Merit 14–18, Excellence 19–24.",
      "N0: no response or no relevant evidence. N1/N2: extracts some (N1) or relevant (N2) material, typically from only ONE source, with a partial attempt at the task.",
      "A3/A4: examines material from the required number of sources and shows understanding of the question; supporting evidence is attempted (A3) or used, possibly with some irrelevant material (A4). For the usefulness/reliability question, shows some awareness of limitations.",
      "M5/M6: examines the material in depth with thorough understanding, explains in the student's OWN WORDS drawing on the sources, with detailed source references; in the reliability question, uses relevant evidence accurately and shows some insight.",
      "E7/E8: examines the material comprehensively or perceptively, with a high degree of engagement with the sources: raises relevant questions, notes limitations, explains the basis for assumptions, and draws conclusions beyond the obvious using both the sources and wider knowledge. E8 requires insightful conclusions and/or relevant questions.",
      "Score each question on its own descriptors. A strong Q1 does not lift a weak Q3; an omitted question scores N0 and usually pulls the total below the Merit or Excellence cut."
     ],
