        "Q2: How did perspectives on the Kīngitanga change or continue over time? Use at least TWO of Sources D–G (sample: a dismissive 1893 colonial source predicting decline; later sources showing continued influence and adaptation; Ngāpuhi solidarity despite earlier resistance).",
