      "M5/M6: examines two effects IN DEPTH with detailed evidence and explanation (minor limitations at M5, none at M6).",
      "E7/E8: examines two effects COMPREHENSIVELY with insight; detailed evidence and relevant, insightful explanation (minor limitations at E7, none at E8).",
