      "2025, Achievement: an event clearly linked to the question; two effects on individuals and/or groups explained; essay structure; relevant evidence lacking detail.",
      "2025, Merit: an event well suited to the task; detailed understanding; distinguished types of impact (social, economic, political) and short- versus long-term effects; detailed, accurate evidence; logical organisation.",
      "2025, Excellence: comprehensive understanding and perceptive discussion with judgements about the SIGNIFICANCE of impacts; some referred to continuity and change; carefully selected evidence often beyond mainstream examples; concise, focused on significance.",
