      "EN2: Apply algebraic methods involves selecting and using methods, demonstrating knowledge of algebraic concepts and terms, and communicating using appropriate representations.",
      "EN2: Relational thinking involves one or more of: selecting and carrying out a logical sequence of steps; connecting different concepts or representations; demonstrating understanding of concepts; forming and using a model. It also involves relating findings to a context, or communicating thinking using appropriate mathematical statements.",
      "EN2: Extended abstract thinking involves one or more of: devising a strategy to investigate or solve a problem; identifying relevant concepts in context; developing a chain of logical reasoning, or proof; forming a generalisation. It also involves using correct mathematical statements, or communicating mathematical insight.",
      "EN3: Problems are situations that give students the opportunity to apply knowledge or understanding of mathematical concepts and methods. Situations are set in real-life or mathematical contexts.",
