      "Each of the three questions is scored separately from N0 to E8, and the three scores are added for a total out of 24.",
      "Grade symbols used in the schedule: u = Achievement-level evidence, r = Merit-level evidence (relational thinking), t = Excellence-level evidence (extended abstract thinking). NZQA does not print a definition of the letters; their meaning comes from the column each sits in (Achievement / Achievement with Merit / Achievement with Excellence) and the standard's criteria. There is no 'e' symbol: Excellence evidence is written t.",
      "2025 code row (read upwards, each code needs at least this evidence in the question): NØ = 'No response; no relevant evidence.' N1 = 'A valid attempt at one question.' N2 = 1u. A3 = 2u. A4 = 3u. M5 = 1r. M6 = 2r. E7 = 1t. E8 = 2t.",
      "2024 code row: the same (NØ, N1 'A valid attempt at one question', then 1u, 2u, 3u, 1r, 2r, 1t, 2t). In 2024 the Excellence evidence for the proof parts, Q1(e) and Q3(e), was split into T1 = 'Derives result but with incorrect mathematical statements' and T2 = 'Mathematically correct proof'.",
      "Notes printed in the evidence column include 'beware of RAWW' (right answer, wrong working: no credit when the answer is right only by accident), 'Accept line 2', 'Other valid approaches are also acceptable', 'Other clearly valid approach with minor numerical error' (can still earn r or t), and 'simplest form of last line not required' where stated.",
      "Correct answer only: the 2024 report states that answers without the working needed are graded 'Correct Answer Only', which earns at most a u.",
      "Cut scores (out of 24): 2025 N 0–7, A 8–13, M 14–19, E 20–24. 2024 N 0–7, A 8–13, M 14–19, E 20–24.",
      "The schedule does not say in words whether an r also counts as a u. Because the codes are read as the highest one whose requirement is met (e.g. one r gives M5 even if there are fewer than 3 u), this only matters at the Achievement codes. Teachers should apply their department's agreed reading consistently."
