      "2025, all three papers: weak basic algebra and fractions limited access to every paper; show clear working; mark clearly which answer is to be marked; attempt every part because parts are not in order of difficulty.",
      "2024, Achievement: found the discriminant, factorised and solved quadratics, identified correct factors but expanded wrongly or could not finish simultaneous equations, cross-multiplied but did not expand correctly (Q2c), and used a common base or logs on both sides (Q3).",
