   "discipline": "Both Level 2 Media Studies exams are single essays, each marked as a whole with one score from 0 to 8. In each, the student argues the extent to which they agree or disagree with ONE statement chosen from five unseen statements. Markers judge the step from describing (A), to explaining how and/or why with relevant evidence (M), to examining consequences or implications and drawing conclusions with carefully chosen secondary evidence and nuance (E). The response must stay on the statement throughout and be grounded in a SPECIFIC media product and audience (91248) or a genre shown through a range of texts (91251). Plot description, name-dropped theorists, rote-learned essays and length are not rewarded.",
