     "assessmentReport": [
      "2025, Achievement: described how the relationship operated with detailed product evidence, but was vague about the audience's characteristics. Referred to theory or secondary sources without showing how they clarified the relationship. Included material that was largely irrelevant or not clearly linked to the statement's key words.",
      "2025, Merit: explored why the relationship exists and how it is built, used statistics, quotes and theory accurately and confidently, referred consistently to the statement's key ideas, and attempted a wider consequence without enough depth, evidence or logic for Excellence.",
      "2025, Excellence: wrote fluently with a clear stance on the statement (not referring to it mechanically), showed thorough knowledge and an understanding of nuance and complexity, discussed the changing media landscape (technology, AI, algorithms), used quotes and theory to unpack points, and developed wider consequences that strengthened the argument.",
      "2025, Not Achieved: well under the suggested length, superficial knowledge (often of a self-selected product), a product too vague or broad (such as a genre), or the statement not addressed sufficiently.",
      "2025, common errors: confusing a media GENRE with a media PRODUCT (genre essays such as 'the road movie' generally performed poorly), treating the statement as an add-on at the end of paragraphs, name-dropping theorists without linking them to the argument, and confusing a product's 'audience' with 'society'. Popular products: Stranger Things, Aroha Bridge, NZTA TVCs, The Gone and Alone Australia, Barbie, Snack Masters, Taylor Swift: The Eras Tour.",
      "2025, commentary: psychographic profiling and other audience theory helped candidates explain how and why the relationship operates. Products with interesting or complex wider implications gave a clear pathway to Excellence.",
      "2024, Achievement: described the relationship, often without a precise sense of the audience's make-up, gave detailed product evidence, and referred to theory without sound understanding, with some material not tied to the statement.",
      "2024, Merit: explored why the relationship exists and how it is built, used statistics, quotes and theory accurately, consistently referred back to the statement's key words, and attempted a wider consequence without enough depth.",
      "2024, Excellence: took a stance on the statement, thought through the nuances and complexities of the relationship independently, included developments in the changing media landscape (technology, AI, algorithms) and their implications, and used secondary evidence extensively.",
      "2024, commentary: some candidates stretched 'media product' to a loose group of related products, but the standard requires a single product and its audience. Multi-season products can show how the relationship develops over time, and a one-off film with distinctive audience engagement also works."
     ],
