   "discipline": "The Level 2 works exam (91277) is marked holistically. Markers read the whole answer booklet and give one score from 0 to 8, judged on how well the student COMPARES two substantial, contrasting works they have studied: first the contexts of the works, then the use of one musical element. The scale runs from simple (A), to detailed (M), to perceptive (E) comparison, supported by specific musical evidence and a reference to the score of at least one work. Biography, narrative, lyrics, generic adjectives ('smooth', 'thick') and pre-prepared essays that do not answer the question are never the criterion. Concise, accurate, targeted writing scores higher than length.",
   "parallelHint": "a different pair of substantial, contrasting works (for example Gershwin's Rhapsody in Blue and Gareth Farr's From the Depths Sound the Great Sea Gongs instead of Beethoven's Symphony No. 5 and Marvin Gaye's What's Going On), or a different element from the paper's list (melody, rhythm, texture, structure, tonality, timbre)",
