      "N0: no response or no relevant evidence. N1: simply describes an aspect of the context of ONE work / identifies an element used in one work. N2: simply describes context for BOTH works / identifies an element in both, but without comparison.",
      "A3/A4: a SIMPLE comparison of how each work's context influences the communication of ideas (2024: reflects lived experience), and a simple comparison of how the chosen element creates unity or contrast (2024: defines both works); supported by simple description and simple musical evidence. Descriptions of each work may be uneven.",
      "M5/M6: a DETAILED comparison of the same points, with detailed description of context and SPECIFIC musical evidence.",
