     "assessmentReport": [
      "2025, commentary: quality declined noticeably, 'the lowest point in nearly a decade'. Work selection was pivotal: many works were chosen for familiarity or personal meaning rather than musical depth, and some were unsuitable for a classroom.",
      "2025, part (a): many relied on biography. Stronger answers covered historical, cultural, political or social factors and explained how they shaped the composer's MUSICAL choices. Some raised contemporary social issues without a substantial work to explore them.",
      "2025, part (b): core terminology was often weak. Tonality was confused with harmony, melody was discussed without ideas, devices or range, rhythm was reduced to time signature and metre, and texture was described with broad adjectives. Melody or structure produced stronger answers. The unity or contrast follow-up was challenging.",
      "2025, Achievement: all parts answered, simple explanations of elements, simple evidence and basic comparisons, usually about instrumentation or structure; whole albums or musicals made answers less specific.",
      "2025, Merit: answered closely and directly with musical evidence, and analysed the social context of the composer's world beyond their personal circumstances.",
      "2025, Excellence: thorough understanding, targeted answers, works with breadth for the unity and contrast question, both works with scores, clear similarities and differences, concise and direct writing.",
      "2025, Not Achieved: incomplete answers, no musical evidence, answers that did not address the question, confused elements (texture as 'light' or 'thick', rhythm as time signature, harmony as key only), insubstantial works, or pre-prepared answers.",
      "2025, advice: plan to avoid repetition; concise, accurate answers beat long ones; reference the score WITH BAR NUMBERS and go beyond referencing to analysis; include at least one Western art music work (NZ and contemporary art music also did well). Works linked to strong results: Beethoven Symphony No. 5 and Piano Concerto No. 3, Bach Brandenburg Concerto No. 5, Gershwin Rhapsody in Blue, Miles Davis So What, John Williams Jaws Suite, Tchaikovsky 1812 Overture, Marvin Gaye What's Going On, Nyman MGV, Psathas Waiting for the Aeroplane, Lilburn Aotearoa Overture, Farr From the Depths Sound the Great Sea Gongs, McLeod Childhood.",
      "2024, commentary: programme-music answers often narrated the story instead of how the elements convey it. Song answers discussed lyrics and context without linking text to the score; stronger ones used prosody or word-painting. Musical language was generalised ('smooth', 'jumpy'). Comparison improved. Melody answers were stronger with specifics (key, intervals, instrumentation, tempo, articulation, placement). Recent popular songs without an accurate score limit evidence. Bar-by-bar accounts rarely led to insight.",
      "2024, Achievement: simple explanations, social context not always specific to the composer, simple evidence and comparison; well-constructed prepared answers that did not answer the question limited the grade. Merit: genre-specific language with understanding, detailed evidence but without further depth. Excellence: thorough, perceptive understanding of both works, both with scores, insights linking the works to how they were created, concise writing with well-chosen evidence. Not Achieved: confused elements, generic answers, incomplete or inconsistent papers."
     ],
