   "discipline": "Each Level 2 Physics exam has three questions. Each question gets its own score code (N0–E8) from the a/m/e evidence ticks the marker gives to its parts, and the three codes are totalled out of 24. Achievement shows awareness of how simple facets of the physics relate to the described situation (one-step calculations, identifying the phenomenon, a correct diagram). Merit gives reasons why, and solves problems where the information is not directly usable. Excellence shows the connections between concepts, usually as a full multi-step solution or a complete linked explanation that answers every bullet point in the context, with correct units, significant figures and directions. Rote past-paper answers not adapted to the context, and numbers without stated meaning, do not earn the higher ticks.",
